package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import static com.aliothmoon.maafw.once.BingNavigationFixture.*;
public class TimedHiddenOwnerGuardTest {
 static String hidden(String c,String w,String a){return window(c,w,false).replace("rootTaskId=15","rootTaskId=99")+"    mActivityRecord=ActivityRecord{"+a+" u0 "+c+" t99}\n";}
 static BingNavigationSnapshot.TimedTaskGuard p(String w,String a){return BingNavigationSnapshot.parseTimedTaskGuard(w,a,PROFILE,RootReadOnlyAnimationGuardTest.G,TimedTaskGuardTest.original(),6000,6010);}
 @Test public void unrelatedSafelyHiddenBingTaskDoesNotJoinCurrentChain(){String c="com.microsoft.bing/com.microsoft.sapphire.other.HiddenActivity";assertTrue(p(TimedInternalTaskGuardTest.w()+hidden(c,"abcd","def0"),TimedInternalTaskGuardTest.a()+activityBlock(c,"def0","99",false)).matches(TimedTaskGuardTest.original(),6010));}
 @Test public void hiddenDuplicateComponentUsesNoGlobalComponentUniqueness(){String c=TimedInternalTaskGuardTest.SEARCH;assertTrue(p(TimedInternalTaskGuardTest.w()+hidden(c,"abcd","def0"),TimedInternalTaskGuardTest.a()+activityBlock(c,"def0","99",false)).matches(TimedTaskGuardTest.original(),6010));}
 @Test public void visibleExtraWindowOrUnprovenHiddenStillRejects(){String c=TimedInternalTaskGuardTest.SEARCH;for(String extra:new String[]{hidden(c,"abcd","def0").replace("isVisible=false","isVisible=true"),hidden(c,"abcd","def0").replace("isOnScreen=false","missingOnScreen")})assertFalse(p(TimedInternalTaskGuardTest.w()+extra,TimedInternalTaskGuardTest.a()+activityBlock(c,"def0","99",false)).matches(TimedTaskGuardTest.original(),6010));}
 @Test public void focusAppAndOriginalExactLinksCannotBeBorrowedFromHiddenSibling(){assertFalse(p(TimedInternalTaskGuardTest.w().replace("mCurrentFocus=Window{bbb","mCurrentFocus=Window{abcd")+hidden(TimedInternalTaskGuardTest.SEARCH,"abcd","def0"),TimedInternalTaskGuardTest.a()+activityBlock(TimedInternalTaskGuardTest.SEARCH,"def0","99",false)).matches(TimedTaskGuardTest.original(),6010));assertFalse(p(TimedInternalTaskGuardTest.w().replace("mActivityRecord=ActivityRecord{ddd","mActivityRecord=ActivityRecord{ddd0"),TimedInternalTaskGuardTest.a()).matches(TimedTaskGuardTest.original(),6010));}
}
